import{c as s,Q as t,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const i="/assets/%E5%B8%A6%E6%9C%89Batch%E8%BD%B4%E7%9A%84Bias%E8%AE%A1%E7%AE%97%E7%A4%BA%E6%84%8F%E5%9B%BE.ClMxTZct.png",l="/assets/%E5%A4%8D%E7%94%A8Bias%E8%AE%A1%E7%AE%97%E7%A4%BA%E6%84%8F%E5%9B%BE.e9kYOvWM.png",d=JSON.parse('{"title":"Batch Matmul复用Bias矩阵","description":"","frontmatter":{},"headers":[{"level":1,"title":"Batch Matmul复用Bias矩阵","slug":"batch-matmul复用bias矩阵"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/Batch-Matmul复用Bias矩阵.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/Batch-Matmul复用Bias矩阵.md"}'),c={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/Batch-Matmul复用Bias矩阵.md"};function p(r,a,o,m,B,h){return t(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="batch-matmul复用bias矩阵" tabindex="-1">Batch Matmul复用Bias矩阵 <a class="header-anchor" href="#batch-matmul复用bias矩阵" aria-label="Permalink to &quot;Batch Matmul复用Bias矩阵&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>在Batch Matmul场景中，Matmul API可以一次性计算出多个大小为singleCoreM * singleCoreN的C矩阵。当Batch Matmul场景有Bias输入时，默认的Bias输入矩阵包含Batch轴，即Bias的大小为Batch * N。通过开启Bias复用功能，当每个Batch计算使用的Bias数据相同时，只需输入一个不带Batch轴的Bias矩阵。Batch Matmul的Bias矩阵复用功能默认不启用，用户需要设置<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">MatmulConfig</a>中的isBiasBatch参数为false来开启此功能。</p><p><strong>图 1</strong> 带有Batch轴的Bias计算示意图<br><img src="'+i+'" alt="" title="带有Batch轴的Bias计算示意图"></p><p>如上图所示，Batch Matmul中未复用Bias矩阵的场景，每计算出一个singleCoreM * singleCoreN大小的C矩阵，都会与1 * singleCoreN大小的Bias矩阵相加。若不同Batch的计算使用的Bias数据相同，则多Batch计算可以复用同一个Bias矩阵，如下图所示，此场景中调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetBias.md" target="_blank" rel="noreferrer">SetBias</a>接口时，只需设置一个1 * singleCoreN大小的Bias矩阵。</p><p><strong>图 2</strong> 复用Bias计算示意图<br><img src="'+l+`" alt="" title="复用Bias计算示意图"></p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>Batch Matmul中每个Batch的Matmul计算可以使用相同的Bias矩阵。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>A、B、C矩阵的Layout类型都为NORMAL时，不支持<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">batchMode</a>参数设为SINGLE_LARGE_THAN_L1，即Bias复用场景下，单Batch的A、B矩阵数据总和不得超过L1 Buffer的大小。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/batch_matmul_bias_reuse" target="_blank" rel="noreferrer">BatchMatmul复用Bias算子样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 自定义MatmulConfig参数，将其中的isBiasBatch参数设置为false，使能BatchMatmul的Bias复用功能。</span></span>
<span class="line"><span>constexpr MatmulConfigMode configMode = MatmulConfigMode::CONFIG_NORM;</span></span>
<span class="line"><span>constexpr MatmulBatchParams batchParams = {</span></span>
<span class="line"><span>  false, BatchMode::BATCH_LESS_THAN_L1, false /* isBiasBatch */</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>constexpr MatmulConfig CFG_MM = GetMMConfig&lt;configMode&gt;(batchParams);</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_MM&gt; mm;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling); // 初始化matmul对象</span></span>
<span class="line"><span>mm.SetTensorA(gm_a);    // 设置左矩阵A</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);    // 设置右矩阵B</span></span>
<span class="line"><span>mm.SetBias(gm_bias);    // 设置Bias，矩阵大小为1 * singleCoreN</span></span>
<span class="line"><span>mm.IterateBatch(gm_c, batchA, batchB, false);</span></span>
<span class="line"><span>mm.End();</span></span></code></pre></div>`,13)])])}const _=s(c,[["render",p]]);export{d as __pageData,_ as default};
